from pathlib import Path
import json,hashlib,base64,sys,time,datetime,resource,traceback
R=Path('/mnt/seagate10tb/orbit-segmented-v4-florianpfaff/shifted-diagnostic-01')
def identity(p):
 p=Path(p);b=p.read_bytes();return {'path':str(p),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
pipeline=identity(R/'control/pipeline.json');assert pipeline['sha256']=='97fe0ff0091bee2b439bb958b36a3fd351242b30fad652e7412eac875eeaf9a6'
j=json.loads((R/'control/pipeline.json').read_text());assert j['status']=='passed' and j['final_cleanup']['verified'] and not j['final_cleanup']['errors']
live=[];seen=set()
for c in j['final_cleanup']['commands']:
 assert c['verified'] and not c['live_owned_processes']
 for v in c['identities']:
  key=(v['pid'],v['start_ticks']);seen.add(key)
  try:fields=Path('/proc/%d/stat'%v['pid']).read_text().rsplit(')',1)[1].split()
  except FileNotFoundError:continue
  if int(fields[19])==v['start_ticks'] and fields[0]!='Z':live.append(v)
assert not live
code=base64.b64decode('');assert hashlib.sha256(code).hexdigest()=='80387e589ed57f7469113764c9540c77a264ef8abbb8f0bf0e249fd810261c86'
scope={'__name__':'audit_module'};exec(compile(code,'audit_shifted_rows02.py','exec'),scope)
start=time.monotonic();envelope={'schema':'orbit-poc-shifted-row-analysis-execution-v1','pipeline':pipeline,'runtime':identity(sys.executable),'runtime_version':sys.version,'observed_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exact_owned_identities_checked':len(seen),'live_exact_owned':live,'affinity':sorted(__import__('os').sched_getaffinity(0)),'helper_sha256':hashlib.sha256(code).hexdigest()}
try:
 result=scope['audit'](R)
 for method in result['methods']:
  for profile in method['profiles']:
   for call in profile['calls']:
    for k in ('input','output'):assert identity(call[k]['path'])==call[k]
 assert identity(R/'control/pipeline.json')==pipeline
 envelope.update(status='passed',result=result)
except Exception as e:envelope.update(status='failed',error=repr(e),traceback=traceback.format_exc())
envelope.update(elapsed_seconds=time.monotonic()-start,peak_rss_kib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss)
print(json.dumps(envelope,sort_keys=True));sys.exit(0 if envelope['status']=='passed' else 1)
